def UniformSmallSetMass (x : ℕ → Lp 𝕜 1 μ) : Prop :=
  ∀ ε : ℝ, 0 < ε → ∃ δ : ℝ≥0∞, 0 < δ ∧
    ∀ n A, MeasurableSet A → μ A ≤ δ → (∫ a in A, ‖x n a‖ ∂μ) ≤ ε

